// Live physics inside the app. Real: app/sim (S4, MuJoCo). Fake: FakeSimulation (kinematic rover).
#pragma once
#include <cstdint>
#include <map>
#include <string>

#include "fulmetry/core/Math.h"
#include "fulmetry/core/Result.h"

namespace fulmetry {

struct DriveInput {
    double throttle = 0;  // -1..1
    double steer = 0;     // -1..1, positive turns left
};

class ISimulation {
public:
    virtual ~ISimulation() = default;
    // MJCF text (generated by the worker from the build123d assembly).
    virtual Status loadModel(const std::string& mjcfXml) = 0;
    virtual void reset(uint64_t seed) = 0;
    virtual void setDriveInput(const DriveInput& input) = 0;
    virtual void setControl(const std::string& actuator, double value) = 0;
    virtual void step(double dtSeconds) = 0;          // advances in fixed internal substeps
    virtual double time() const = 0;
    virtual Result<Transform> bodyPose(const std::string& body) const = 0;
    // Live panel: speed_mps, current_a, battery_pct, rssi_dbm, surface, ...
    virtual std::map<std::string, double> telemetry() const = 0;
    // Hash of the state so far; same model + seed + inputs must give the same hash.
    virtual uint64_t stateHash() const = 0;
};

}  // namespace fulmetry
